--
-- Struktura tabeli dla tabeli `pages`
--

CREATE TABLE `pages` (
  `id` int(11) NOT NULL,
  `url` varchar(255) COLLATE utf8_polish_ci NOT NULL,
  `title` varchar(255) COLLATE utf8_polish_ci NOT NULL,
  `title_seo` varchar(255) COLLATE utf8_polish_ci NOT NULL,
  `img` varchar(255) COLLATE utf8_polish_ci DEFAULT NULL,
  `img_title` varchar(255) COLLATE utf8_polish_ci DEFAULT NULL,
  `content` text COLLATE utf8_polish_ci NOT NULL,
  `content_short` text COLLATE utf8_polish_ci DEFAULT NULL,
  `description` varchar(255) COLLATE utf8_polish_ci NOT NULL,
  `keywords` varchar(255) COLLATE utf8_polish_ci NOT NULL,
  `show_in_menu` tinyint(1) NOT NULL,
  `who_fill` int(11) NOT NULL,
  `visit` int(11) NOT NULL DEFAULT 0,
  `type` varchar(255) COLLATE utf8_polish_ci NOT NULL DEFAULT 'subpage',
  `realestate_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0 = w realizacji, 1 = zakończona/sprzedana',
  `queue` int(11) NOT NULL DEFAULT 0,
  `queue_menu` int(11) NOT NULL DEFAULT 0,
  `category` int(11) NOT NULL DEFAULT 0,
  `is_hide` tinyint(1) NOT NULL DEFAULT 0,
  `is_published` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `lang` int(11) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_polish_ci;

--
-- Zrzut danych tabeli `pages`
--

INSERT INTO `pages` (`id`, `url`, `title`, `title_seo`, `img`, `img_title`, `content`, `content_short`, `description`, `keywords`, `show_in_menu`, `who_fill`, `visit`, `type`, `realestate_status`, `queue`, `queue_menu`, `category`, `is_hide`, `is_published`, `created_at`, `lang`) VALUES
(0, 'start', 'Start', 'Start | EKO-DOM', NULL, NULL, '', NULL, 'Strona główna EKO-DOM z aktualną ofertą inwestycji.', 'eko-dom, start, inwestycje', 0, 1, 0, 'subpage', 0, 0, 0, 1, 0, 1, '2022-04-01 17:53:30', 1),
(27, 'kontakt', 'Kontakt', 'Kontakt | EKO-DOM – biuro sprzedaży inwestycji', NULL, NULL, '<h2>Kontakt z EKO-DOM</h2><p>Skontaktuj się z biurem sprzedaży EKO-DOM, aby uzyskać informacje o inwestycjach i dostępności domów.</p><p><strong>E-mail:</strong> <a href="mailto:biuro@eko-dom.test">biuro@eko-dom.test</a></p>', NULL, 'Kontakt z biurem sprzedaży EKO-DOM.', 'kontakt eko-dom, biuro sprzedaży', 1, 1, 0, 'subpage', 0, 0, 3, 1, 0, 1, '2022-12-16 16:28:40', 1),
(28, 'blad-404', 'Błąd 404', '', NULL, NULL, '', NULL, '', '', 0, 1, 0, 'subpage', 0, 0, 0, 1, 0, 1, '2022-12-21 13:47:55', 1);

--
-- Dane testowe EKO-DOM (zgodne z info.md: /inwestycje, /developer, /kontakt)
--

UPDATE `pages`
SET
  `title` = 'Kontakt',
  `title_seo` = 'Kontakt | EKO-DOM – biuro sprzedaży inwestycji',
  `content` = '<h2>Skontaktuj się z EKO-DOM</h2><p>Masz pytania o inwestycje lub dostępność domów? Wypełnij formularz kontaktowy i zostaw telefon lub e-mail.</p><h3>Biuro sprzedaży</h3><ul><li>EKO-DOM Sp. z o.o.</li><li>ul. Budowlana 12, 02-001 Warszawa</li><li>tel. +48 500 600 700</li><li>e-mail: biuro@eko-dom.test</li></ul><h3>Godziny pracy</h3><p>Poniedziałek–Piątek: 9:00–17:00</p>',
  `description` = 'Kontakt z biurem sprzedaży EKO-DOM. Umów rozmowę o inwestycjach i dostępnych domach.',
  `keywords` = 'kontakt eko-dom, biuro sprzedaży, inwestycje mieszkaniowe, domy na sprzedaż',
  `show_in_menu` = 1,
  `queue_menu` = 3,
  `category` = 1,
  `is_published` = 1
WHERE `id` = 27;

INSERT INTO `pages` (`id`, `url`, `title`, `title_seo`, `img`, `img_title`, `content`, `content_short`, `description`, `keywords`, `show_in_menu`, `who_fill`, `visit`, `type`, `realestate_status`, `queue`, `queue_menu`, `category`, `is_hide`, `is_published`, `created_at`, `lang`) VALUES
(12001, 'inwestycje', 'Inwestycje', 'Inwestycje | EKO-DOM – aktualna oferta', NULL, NULL, '<h2>Aktualne inwestycje EKO-DOM</h2><p>Poznaj osiedla i domy jednorodzinne realizowane przez EKO-DOM. Sprawdź statusy: Dostępny, Rezerwacja, Sprzedany.</p><h3>Co znajdziesz na stronie inwestycji?</h3><ul><li>galerie i slider zdjęć inwestycji,</li><li>listę domów/lokali z parametrami,</li><li>pliki do pobrania (prospekt, karty lokali, standard wykończenia),</li><li>formularz kontaktowy z wymaganymi zgodami.</li></ul>', 'Przegląd aktualnych inwestycji deweloperskich EKO-DOM.', 'Sprawdź inwestycje EKO-DOM: dostępność domów, statusy oraz dokumenty do pobrania.', 'inwestycje deweloperskie, eko-dom, osiedla, domy na sprzedaż', 1, 1, 0, 'subpage', 0, 0, 1, 1, 0, 1, '2026-03-27 12:00:00', 1),
(12002, 'developer', 'Developer', 'Developer | EKO-DOM – o firmie', NULL, NULL, '<h2>O deweloperze EKO-DOM</h2><p>Budujemy kameralne inwestycje mieszkaniowe z naciskiem na funkcjonalne układy i wysoką jakość wykonania.</p><h3>Dlaczego EKO-DOM?</h3><ul><li>transparentny proces zakupu,</li><li>regularne aktualizacje postępu budowy,</li><li>czytelne statusy dostępności domów.</li></ul><h3>Standard współpracy</h3><p>Zapewniamy opiekę doradcy od pierwszego kontaktu do odbioru kluczy.</p>', 'Poznaj EKO-DOM i standard realizacji inwestycji.', 'Dowiedz się więcej o deweloperze EKO-DOM: doświadczenie, standard realizacji i obsługa klienta.', 'developer eko-dom, deweloper warszawa, o firmie, inwestycje mieszkaniowe', 1, 1, 0, 'subpage', 0, 0, 2, 1, 0, 1, '2026-03-27 12:00:00', 1)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `title_seo` = VALUES(`title_seo`),
  `content` = VALUES(`content`),
  `content_short` = VALUES(`content_short`),
  `description` = VALUES(`description`),
  `keywords` = VALUES(`keywords`),
  `show_in_menu` = VALUES(`show_in_menu`),
  `queue_menu` = VALUES(`queue_menu`),
  `category` = VALUES(`category`),
  `is_hide` = VALUES(`is_hide`),
  `is_published` = VALUES(`is_published`),
  `lang` = VALUES(`lang`);

